"""Generated by the NL to Flow Diagram Encoder Pipeline."""

class Stack:
    def __init__(self, capacity):
        self.arr = [None] * capacity
        self.top_index = (-1)

    def Push(self, item):
        if (self.top_index == (len(self.arr) - 1)):
            return 'Overflow Error'
        self.top_index = (self.top_index + 1)
        self.arr[self.top_index] = item

    def Pop(self):
        if (self.top_index == (-1)):
            return 'Underflow Error'
        item = self.arr[self.top_index]
        self.top_index = (self.top_index - 1)
        return item

    def Peek(self):
        if (self.top_index == (-1)):
            return 'Stack Empty'
        return self.arr[self.top_index]


s = Stack(3)

print(s.Push(10))   # None (success)
print(s.Push(20))   # None
print(s.Push(30))   # None
print(s.Push(40))   # Overflow Error

print(s.Peek())     # 30

print(s.Pop())      # 30
print(s.Pop())      # 20
print(s.Pop())      # 10
print(s.Pop())      # Underflow Error

print(s.Peek())     # Stack Empty
